import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Обзор самостоятельного развёртывания","description":"","frontmatter":{},"headers":[],"relativePath":"ru/self-hosted/index.md","filePath":"ru/self-hosted/index.md","lastUpdated":1792323081000}'),d={name:"ru/self-hosted/index.md"};function h(l,e,s,p,i,n){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="обзор-самостоятельного-развертывания" tabindex="-1">Обзор самостоятельного развёртывания <a class="header-anchor" href="#обзор-самостоятельного-развертывания" aria-label="Permalink to &quot;Обзор самостоятельного развёртывания&quot;">​</a></h1><p>Memoh работает как серверный стек; веб-клиент и настольное приложение — его клиенты. Сначала выберите серверный вариант, а затем решите, как вы будете к нему обращаться.</p><table tabindex="0"><thead><tr><th>Сценарий</th><th>Что выбрать</th><th>Почему</th></tr></thead><tbody><tr><td>Попробовать Memoh, ничего не устанавливая</td><td><a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a></td><td>Управляемый сервис, тот же продукт, не нужно держать собственный сервер.</td></tr><tr><td>Общий сервер, удалённый доступ, публичные/приватные каналы, стабильная работа в продакшене, несколько пользователей или арендаторов</td><td><a href="./docker.html">Server Deploy</a></td><td>Стек Docker Compose поддерживает в рабочем состоянии бэкенд, веб-клиент, PostgreSQL (с pgvector для памяти) и рантайм рабочих пространств.</td></tr><tr><td>Нативное приложение на вашем компьютере, который при желании можно предоставить Bot как Computer</td><td><a href="./desktop.html">Desktop</a></td><td>Нативный клиент, подключающийся к Cloud или вашему серверу; локальный сервер он не запускает.</td></tr></tbody></table><h2 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h2><p>Выбирайте Server Deploy, когда Memoh должен быть доступен нескольким пользователям, работать непрерывно или подключаться к внешним каналам: Telegram, Discord, Feishu, WeChat, официальным аккаунтам WeChat, электронной почте и другим.</p><p>Начните с <a href="./../guides/quick-start.html">Быстрого старта</a> — это самый короткий путь, а полный справочник ищите в <a href="./docker.html">Server Deploy</a>.</p><h2 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h2><p>Выбирайте Desktop, если хотите, чтобы Memoh вёл себя как нативное приложение с иконкой в трее и горячими клавишами, или если серверные Bot должны пользоваться файлами, оболочкой и браузером вашего компьютера. Desktop всегда подключается к серверу (Cloud или самостоятельно развёрнутому); см. <a href="./desktop.html">Desktop</a>.</p><h2 id="связанные-страницы" tabindex="-1">Связанные страницы <a class="header-anchor" href="#связанные-страницы" aria-label="Permalink to &quot;Связанные страницы&quot;">​</a></h2><ul><li><a href="./workspace-backends.html">Бэкенды рабочих пространств</a> — о выборе рантайма рабочих пространств: Docker, containerd, Apple и локальный вариант.</li></ul>',10)])])}const u=t(d,[["render",h]]);export{m as __pageData,u as default};
